import React, { useEffect, useState } from 'react';
import { getFranchises, deleteFranchise, createFranchise, updateFranchise } from '../services/api'; // Import API functions

const FranchiseList = () => {
  const [franchises, setFranchises] = useState([]);
  const [editingFranchise, setEditingFranchise] = useState(null);
  const [formData, setFormData] = useState({
    name: '',
    location: '',
    contactNumber: '',
    status: 'active',
  });
  const [showForm, setShowForm] = useState(false); // State to control form visibility
  const [loading, setLoading] = useState(false); // Loading state for API calls
  const [error, setError] = useState(''); // Error state to capture any errors

  // Fetch franchises when the component loads
  useEffect(() => {
    fetchFranchises();
  }, []);

  const fetchFranchises = async () => {
    setLoading(true);
    setError('');
    try {
      const response = await getFranchises(); // Assuming getFranchises returns an object with 'data' property
      setFranchises(response.data); // Assuming response.data is an array of franchises
    } catch (error) {
      setError('Error fetching franchises: ' + (error.response?.data?.message || error.message));
    } finally {
      setLoading(false);
    }
  };

  const handleDelete = async (id) => {
    if (window.confirm('Are you sure you want to delete this franchise?')) {
      try {
        await deleteFranchise(id);
        alert('Franchise deleted successfully');
        fetchFranchises();
      } catch (error) {
        alert('Error deleting franchise: ' + (error.response?.data?.message || error.message));
      }
    }
  };

  const handleEdit = (franchise) => {
    setEditingFranchise(franchise);
    setFormData({
      name: franchise.name,
      location: franchise.location,
      contactNumber: franchise.contactNumber,
      status: franchise.status,
    });
    setShowForm(true); // Show the form when editing a franchise
  };

  const handleCancelEdit = () => {
    setEditingFranchise(null);
    setFormData({
      name: '',
      location: '',
      contactNumber: '',
      status: 'active',
    });
    setShowForm(false); // Hide the form when canceling edit
  };

  const handleChange = (e) => {
    setFormData({ ...formData, [e.target.name]: e.target.value });
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    try {
      if (editingFranchise) {
        // Update franchise logic
        await updateFranchise(editingFranchise._id, formData); // Use the franchise ID and the form data
        alert('Franchise updated successfully!');
        fetchFranchises(); // Fetch the updated list of franchises
      } else {
        // Create franchise logic
        await createFranchise(formData);
        alert('Franchise created successfully!');
        fetchFranchises(); // Fetch the updated list of franchises
      }
      handleCancelEdit(); // Reset form and state after submission
    } catch (error) {
      alert('Error submitting form: ' + (error.response?.data?.message || error.message));
    }
  };

  return (
    <div>
      <h1>Franchise Management</h1>

      {/* Show "Create Franchise" button only if the form is not already shown */}
      {!showForm && (
        <button onClick={() => setShowForm(true)}>Create Franchise</button>
      )}

      {/* Display loading state */}
      {loading && <p>Loading...</p>}

      {/* Display error message if any */}
      {error && <p style={{ color: 'red' }}>{error}</p>}

      {/* Franchise Form - Only visible when showForm is true */}
      {showForm && (
        <>
          <h2>{editingFranchise ? 'Edit Franchise' : 'Create Franchise'}</h2>
          <form onSubmit={handleSubmit}>
            <div>
              <label htmlFor="name">Name:</label>
              <input
                id="name"
                name="name"
                value={formData.name}
                onChange={handleChange}
                placeholder="Franchise Name"
                required
              />
            </div>
            <div>
              <label htmlFor="location">Location:</label>
              <input
                id="location"
                name="location"
                value={formData.location}
                onChange={handleChange}
                placeholder="Franchise Location"
                required
              />
            </div>
            <div>
              <label htmlFor="contactNumber">Contact Number:</label>
              <input
                id="contactNumber"
                name="contactNumber"
                value={formData.contactNumber}
                onChange={handleChange}
                placeholder="Contact Number"
                required
              />
            </div>
            <div>
              <label htmlFor="status">Status:</label>
              <select id="status" name="status" value={formData.status} onChange={handleChange}>
                <option value="active">Active</option>
                <option value="inactive">Inactive</option>
              </select>
            </div>
            <div>
              <button type="submit">{editingFranchise ? 'Update Franchise' : 'Create Franchise'}</button>
              <button type="button" onClick={handleCancelEdit}>Cancel</button>
            </div>
          </form>
        </>
      )}

      {/* Franchise List */}
      <h2>Franchise List</h2>
      <table>
        <thead>
          <tr>
            <th>Name</th>
            <th>Location</th>
            <th>Contact Number</th>
            <th>Status</th>
            <th>Actions</th>
          </tr>
        </thead>
        <tbody>
          {franchises.length > 0 ? (
            franchises.map((franchise) => (
              <tr key={franchise._id}>
                <td>{franchise.name}</td>
                <td>{franchise.location}</td>
                <td>{franchise.contactNumber}</td>
                <td>{franchise.status}</td>
                <td>
                  <button onClick={() => handleEdit(franchise)}>Edit</button>
                  <button onClick={() => handleDelete(franchise._id)}>Delete</button>
                </td>
              </tr>
            ))
          ) : (
            <tr>
              <td colSpan="5">No franchises available.</td>
            </tr>
          )}
        </tbody>
      </table>
    </div>
  );
};

export default FranchiseList;
